// ================= AUTHENTICATION & VALIDATION =================
const headers = $json.headers || {};
const query = $json.query || {};
const body = $json.body || {};

// 1. Detect CORS OPTIONS Preflight
const method = (headers['x-forwarded-method'] || $json.method || '').toUpperCase();
if (method === 'OPTIONS') {
  return [{
    json: {
      isPreflight: true,
      isAuthorized: true,
      statusCode: 200
    }
  }];
}

// 2. Extract Auth Token from Headers, Query, or Body
const rawAuth =
  headers.authorization ||
  headers.Authorization ||
  headers['x-api-key'] ||
  headers['x-auth-token'] ||
  query.token ||
  body.token ||
  '';

const token = String(rawAuth).replace(/^Bearer\s+/i, '').trim();

// Validate Token Presence (permissive length check consistent with overview & session logs)
const isValid = token.length >= 8;

if (!isValid) {
  return [{
    json: {
      isPreflight: false,
      isAuthorized: false,
      statusCode: 401,
      error: 'Unauthorized',
      message: 'Authentication failed: Missing or invalid authorization token. Access denied.'
    }
  }];
}

// 3. PostgreSQL Query to fetch chat memory entries
const sqlQuery = `SELECT 
  id, 
  session_id, 
  role, 
  message, 
  created_at 
FROM public.chat_memory 
ORDER BY created_at ASC;`;

return [{
  json: {
    isPreflight: false,
    isAuthorized: true,
    statusCode: 200,
    sqlQuery: sqlQuery,
    tokenPreview: token.substring(0, 10) + '...',
    authenticatedAt: new Date().toISOString()
  }
}];

