// ================= IDENTIFY FALLBACKS FROM CHAT_MEMORY =================
let rows = [];
try {
  rows = $('Execute Postgres Query (chat_memory)').all().map(i => i.json).filter(r => r && (r.id || r.session_id));
} catch (e) {
  rows = [];
}

// 1. Group messages by session_id in chronological order
const sessionMap = new Map();
rows.forEach(r => {
  if (!r || !r.session_id) return;
  const sId = String(r.session_id).trim();
  if (!sessionMap.has(sId)) {
    sessionMap.set(sId, []);
  }
  sessionMap.get(sId).push({
    id: r.id,
    sessionId: sId,
    role: (r.role || 'user').toLowerCase().trim(),
    message: String(r.message || '').trim(),
    createdAt: r.created_at ? new Date(r.created_at) : new Date()
  });
});

// Guardrail signature patterns
const PATTERNS = {
  CAROTID: {
    regex: /carotid|front of (my )?neck|throat|anterior neck/i,
    intent: 'SAFETY_CAROTID_PLACEMENT',
    reason: 'Absolute Anatomical Contraindication: Risk of acute hypotension or bradycardia. Placement strictly prohibited.',
    category: 'Safety',
    severity: 'critical'
  },
  CARDIAC: {
    regex: /pacemaker|defibrillator|implanted (cardiac|heart)|icd/i,
    intent: 'CONTRAINDICATION_CARDIAC_DEVICE',
    reason: 'Absolute Clinical Contraindication: Implanted cardiac pacemaker/ICD electrical interference risk. Mandatory physician clearance.',
    category: 'Safety',
    severity: 'critical'
  },
  PREGNANCY: {
    regex: /pregnan|trimester|expecting a baby/i,
    intent: 'CONTRAINDICATION_PREGNANCY_EMS',
    reason: 'Clinical Caution: Electrotherapy requires certified OB/GYN clearance during pregnancy.',
    category: 'Safety',
    severity: 'high'
  },
  HARDWARE_FIRE: {
    regex: /spark|smoking|burnt|burning|melted|shocking me|fire|exploded|thermal runaway/i,
    intent: 'HARDWARE_THERMAL_RUNAWAY',
    reason: 'Catastrophic Hardware Fault: Fire/electrical hazard requiring immediate emergency disconnection.',
    category: 'Hardware',
    severity: 'critical'
  },
  HARDWARE_NO_OUTPUT: {
    regex: /zero stimulation|no stimulation|channel (1|2) not working|no output/i,
    intent: 'HARDWARE_CHANNEL_NO_OUTPUT',
    reason: 'Lead Wire / Circuit Disconnect: Channel continuity or output amplifier issue.',
    category: 'Hardware',
    severity: 'medium'
  },
  PEDIATRIC: {
    regex: /toddler|baby|infant|swallowed.*(wire|pin|electrode)|child.*mouth/i,
    intent: 'EMERGENCY_FOREIGN_BODY_INGESTION',
    reason: 'Acute Pediatric Emergency: Device indicated for adult use only; Poison Control / emergency dispatch rule.',
    category: 'Emergency',
    severity: 'critical'
  },
  PHARMACEUTICAL: {
    regex: /dosage.*(ibuprofen|tylenol|aspirin|advil|mg|pill)|what dose/i,
    intent: 'PHARMACEUTICAL_ADVICE_REQUEST',
    reason: 'Medical Scope Exceeded: Spark AI does not dispense pharmacological dosing recommendations.',
    category: 'Policy',
    severity: 'medium'
  },
  OVERNIGHT: {
    regex: /bypass.*(timer|shutoff)|sleep with.*overnight|run.*all night/i,
    intent: 'OVERNIGHT_UNSUPERVISED_USE',
    reason: 'Sleep Hazard Policy: Overnight stimulation increases risk of skin necrosis; override rejected.',
    category: 'Policy',
    severity: 'high'
  },
  OUT_OF_DOMAIN: {
    regex: /write (me )?a (poem|essay|story)|recipe for|weather in|who won the/i,
    intent: 'OUT_OF_CONTEXT_REQUEST',
    reason: 'Domain Boundary Policy: Inquired about non-PMT topic; off-topic guardrail activated.',
    category: 'Domain',
    severity: 'info'
  },
  TYPO: {
    regex: /^[a-z]{1,2}$|^[^\w\s]+$/i,
    intent: 'TYPO_OR_GIBBERISH',
    reason: 'Input Hygiene Guardrail: Low-entropy or unreadable text detected in prompt.',
    category: 'Validation',
    severity: 'info'
  }
};

const identifiedFallbacks = [];
const seenKeys = new Set();

sessionMap.forEach((messages, sId) => {
  // Sort ascending by time
  messages.sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime());

  for (let i = 0; i < messages.length; i++) {
    const cur = messages[i];

    // Method A: If message is from assistant and contains a known fallback response
    if (cur.role === 'assistant') {
      const text = cur.message.toLowerCase();
      let matchedIntent = null;
      let matchedReason = null;
      let matchedCategory = 'Fallback';
      let matchedSeverity = 'medium';

      if (text.includes("sorry, i couldn't find a relevant answer") || 
          text.includes("could not find a relevant answer") || 
          text.includes("contact pmt support directly")) {
        matchedIntent = 'KNOWLEDGE_BASE_MISS';
        matchedReason = 'Knowledge Base Miss: Query did not match verified PMT clinical documentation or device manual.';
        matchedCategory = 'KB Miss';
        matchedSeverity = 'medium';
      } else if (text.includes("i specialize exclusively in pmt products") || 
                 text.includes("dedicated pain management technologies (pmt) assistant")) {
        matchedIntent = 'OUT_OF_CONTEXT_REQUEST';
        matchedReason = 'Domain Boundary Policy: Inquired about non-PMT topic; off-topic guardrail activated.';
        matchedCategory = 'Domain';
        matchedSeverity = 'info';
      } else if (text.includes("typo detected")) {
        matchedIntent = 'TYPO_OR_GIBBERISH';
        matchedReason = 'Input Hygiene Guardrail: Low-entropy or unreadable text detected in prompt.';
        matchedCategory = 'Validation';
        matchedSeverity = 'info';
      } else if (text.includes("pacemaker") || text.includes("defibrillator")) {
        matchedIntent = 'CONTRAINDICATION_CARDIAC_DEVICE';
        matchedReason = 'Clinical Contraindication: Pacemaker/ICD electrical interference hazard. Mandatory physician clearance.';
        matchedCategory = 'Safety';
        matchedSeverity = 'critical';
      } else if (text.includes("carotid") || text.includes("front of neck")) {
        matchedIntent = 'SAFETY_CAROTID_PLACEMENT';
        matchedReason = 'Absolute Anatomical Contraindication: Risk of severe bradycardia or acute blood pressure drops.';
        matchedCategory = 'Safety';
        matchedSeverity = 'critical';
      } else if (text.includes("pregnant") || text.includes("pregnancy")) {
        matchedIntent = 'CONTRAINDICATION_PREGNANCY_EMS';
        matchedReason = 'Clinical Contraindication: Electrotherapy requires certified OB/GYN clearance during pregnancy.';
        matchedCategory = 'Safety';
        matchedSeverity = 'high';
      } else if (text.includes("spark") || text.includes("smoke") || text.includes("burning")) {
        matchedIntent = 'HARDWARE_THERMAL_RUNAWAY';
        matchedReason = 'Catastrophic Hardware Fault: Fire/electrical hazard requiring immediate emergency disconnection.';
        matchedCategory = 'Hardware';
        matchedSeverity = 'critical';
      } else if (text.includes("pharmacological") || text.includes("dosage")) {
        matchedIntent = 'PHARMACEUTICAL_ADVICE_REQUEST';
        matchedReason = 'Medical Scope Exceeded: Spark AI does not dispense pharmacological dosing recommendations.';
        matchedCategory = 'Policy';
        matchedSeverity = 'medium';
      }

      if (matchedIntent) {
        // Find preceding user question in this session
        let triggerQ = 'Clinical inquiry in session #' + sId;
        for (let j = i - 1; j >= 0; j--) {
          if (messages[j].role === 'user' && messages[j].message) {
            triggerQ = messages[j].message;
            break;
          }
        }

        const dedupKey = sId + '|' + matchedIntent + '|' + triggerQ;
        if (!seenKeys.has(dedupKey)) {
          seenKeys.add(dedupKey);
          identifiedFallbacks.push({
            id: cur.id || ('FB-' + (identifiedFallbacks.length + 1)),
            sessionId: sId,
            triggerQuery: triggerQ,
            detectedIntent: matchedIntent,
            fallbackReason: matchedReason,
            category: matchedCategory,
            severity: matchedSeverity,
            timestamp: cur.createdAt.toISOString().replace('T', ' ').slice(0, 19) + ' UTC',
            rawTimestamp: cur.createdAt.toISOString()
          });
        }
      }
    }

    // Method B: If message is from user, evaluate against guardrail triggers directly
    if (cur.role === 'user' && cur.message) {
      for (const [key, p] of Object.entries(PATTERNS)) {
        if (p.regex.test(cur.message)) {
          const dedupKey = sId + '|' + p.intent + '|' + cur.message;
          if (!seenKeys.has(dedupKey)) {
            seenKeys.add(dedupKey);
            identifiedFallbacks.push({
              id: cur.id || ('FB-' + (identifiedFallbacks.length + 1)),
              sessionId: sId,
              triggerQuery: cur.message,
              detectedIntent: p.intent,
              fallbackReason: p.reason,
              category: p.category,
              severity: p.severity,
              timestamp: cur.createdAt.toISOString().replace('T', ' ').slice(0, 19) + ' UTC',
              rawTimestamp: cur.createdAt.toISOString()
            });
          }
          break; // Stop after first matched pattern for this user message
        }
      }
    }
  }
});

// Sort identified fallbacks by timestamp descending (newest first)
identifiedFallbacks.sort((a, b) => new Date(b.rawTimestamp).getTime() - new Date(a.rawTimestamp).getTime());

// Calculate KPI summary
let safetyCount = 0;
let kbMissCount = 0;
let hardwareCount = 0;
let policyCount = 0;
const intentMap = {};

identifiedFallbacks.forEach(f => {
  if (f.category === 'Safety') safetyCount++;
  else if (f.category === 'KB Miss') kbMissCount++;
  else if (f.category === 'Hardware') hardwareCount++;
  else policyCount++;

  intentMap[f.detectedIntent] = (intentMap[f.detectedIntent] || 0) + 1;
});

let topIntent = '--';
let maxCount = 0;
Object.entries(intentMap).forEach(([intent, count]) => {
  if (count > maxCount) {
    maxCount = count;
    topIntent = intent;
  }
});

const kpi = {
  total_fallbacks: identifiedFallbacks.length,
  safety_guardrails_count: safetyCount,
  kb_misses_count: kbMissCount,
  hardware_faults_count: hardwareCount,
  policy_violations_count: policyCount,
  top_intent: topIntent,
  recent_incident: identifiedFallbacks[0]?.timestamp || 'None recorded'
};

return [{
  json: {
    success: true,
    status: 200,
    kpi: kpi,
    fallbacks: identifiedFallbacks,
    total_count: identifiedFallbacks.length,
    generated_at: new Date().toISOString()
  }
}];
